pub fn encode(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for &byte in bytes {
        out.push(DIGITS[(byte >> 4) as usize] as char);
        out.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    out
}

pub(crate) fn supersede_habit(
    &mut self,
    old: i64,
    new: i64,
    old_revision: &str,
    new_revision: &str,
) -> SqlResult<HabitSupersessionReceipt> {
    if old <= 0 || new <= 0 || old == new {
        return Err(invalid(
            "replacement requires two different positive habit IDs",
        ));
    }
    if !super::super::collection::valid_id(old_revision)
        || !super::super::collection::valid_id(new_revision)
    {
        return Err(invalid(
            "both review revisions must be full 64-character keys",
        ));
    }
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    if let Some(receipt) = committed_receipt(&tx, old, new, old_revision, new_revision)? {
        return Ok(receipt);
    }
    let Some(old_habit) = habit_review::read_habits(&tx, Some(old))?
        .into_iter()
        .next()
    else {
        return Err(invalid("old habit missing"));
    };
    let Some(new_habit) = habit_review::read_habits(&tx, Some(new))?
        .into_iter()
        .next()
    else {
        return Err(invalid("new habit missing"));
    };
    if old_habit.review_revision() != old_revision
        || new_habit.review_revision() != new_revision
    {
        return Err(invalid(
            "review revision changed; inspect both habits again",
        ));
    }
    if old_habit.scope != new_habit.scope
        || old_habit.role != new_habit.role
        || old_habit.workflow != new_habit.workflow
    {
        return Err(invalid(
            "replacement requires the same scope, role and workflow",
        ));
    }
    for habit in [&old_habit, &new_habit] {
        if !matches!(habit.status.as_str(), "candidate" | "stale" | "observed")
            || habit.retired_status().is_some()
        {
            return Err(invalid(
                "rejected or superseded habits cannot take part in a new replacement",
            ));
        }
    }
    if let Some(reason) = new_habit.observation_problem() {
        return Err(invalid(reason));
    }
    // Both endpoints have no outgoing edge and the predecessor is unique.
    // Together with no self-link, this prevents cycles without graph walks.
    let at: i64 = tx.query_row("SELECT unixepoch()", [], |r| r.get(0))?;
    tx.execute("INSERT INTO persona_habit_supersession(old_id,new_id,old_revision,new_revision,reviewed_at) VALUES (?1,?2,?3,?4,?5)",params![old,new,old_revision,new_revision,at])?;
    tx.execute(
        "UPDATE persona_claim SET status='superseded' WHERE id=?1",
        [old],
    )?;
    tx.execute(
        "DELETE FROM persona_habit_observation WHERE claim_id=?1",
        [old],
    )?;
    tx.execute(
        "UPDATE persona_claim SET status='observed' WHERE id=?1",
        [new],
    )?;
    tx.execute("INSERT INTO persona_habit_observation(claim_id,revision) VALUES (?1,?2) ON CONFLICT(claim_id) DO UPDATE SET revision=excluded.revision",params![new,new_revision])?;

/// The latest explicit transfer supplies the verification mode and exact
/// immutable locator. Later manual re-citation cannot downgrade this mode.
pub(crate) fn habit_candidate_binding(
    &self,
    evidence_id: i64,
) -> SqlResult<Option<CollectedCandidate>> {
    if !self.has_table("persona_candidate_habit")? {
        return Ok(None);
    }
    let raw: Option<String> = self
        .conn
        .query_row(
            "SELECT candidate_json FROM persona_candidate_habit WHERE evidence_id=?1
         ORDER BY rowid DESC LIMIT 1",
            [evidence_id],
            |row| row.get(0),
        )
        .optional()?;
    raw.map(|raw| {
        if raw.len() > 16 * 1024 {
            return Err(invalid("candidate provenance exceeds its bound"));
        }
        serde_json::from_str(&raw).map_err(|_| invalid("invalid candidate provenance"))
    })
    .transpose()
}

pub(super) fn evaluate(input_path: &Path, config: &RefinerConfig) -> Result<Value, Error> {
    let started = Instant::now();
    let result = (|| {
        let input = read_input(input_path)?;
        config.validate().map_err(|_| "configuration_invalid")?;
        let _cancellation =
            worker::Cancellation::install().map_err(|_| "process_supervision_unavailable")?;
        let response =
            refiner::process(&input, config).map_err(|_| "processing_or_validation_failed")?;
        if worker::interrupted() {
            return Err("interrupted");
        }
        Ok(response)
    })();
    Ok(match result {
        Ok(response) => json!({
            "schema": 1,
            "status": "evaluated",
            "admission": false,
            "response": serde_json::to_value(response)?,
            "elapsed_ms": started.elapsed().as_millis(),
        }),
        Err(reason) => json!({
            "schema": 1,
            "status": "failed",
            "admission": false,
            "reason": reason,
            "elapsed_ms": started.elapsed().as_millis(),
        }),
    })
}

pub(super) fn parse_response(input: &Input, bytes: &[u8]) -> Result<Response, Error> {
    validate_input(input)?;
    if bytes.len() > MAX_RESPONSE_BYTES {
        return Err("refiner response exceeds 64 KiB".into());
    }
    let value = crate::setup::parse_json_unique(bytes)
        .map_err(|_| "refiner response must be one JSON object with unique keys")?;
    // Serde accepts missing Option fields as None. The wire protocol requires
    // them explicitly, so absence cannot silently become a valid null.
    if !value.as_object().is_some_and(|object| {
        object.contains_key("intent_evidence") && object.contains_key("refined_prompt")
    }) {
        return Err("refiner response must include every schema-1 field".into());
    }
    let response: Response = serde_json::from_value(value)
        .map_err(|_| "refiner response does not match the strict schema-1 contract")?;
    validate_response(input, &response)?;
    Ok(response)
}

impl Cancellation {
    #[cfg(unix)]
    pub(super) fn install() -> Result<Self, Error> {
        // SAFETY: zeroed sigaction structs are initialized through libc before
        // registration. The handler only writes a lock-free atomic boolean.
        unsafe {
            let mut action: libc::sigaction = std::mem::zeroed();
            let mut previous: [libc::sigaction; 2] = std::mem::zeroed();
            action.sa_sigaction = interrupt as *const () as usize;
            libc::sigemptyset(&mut action.sa_mask);
            INTERRUPTED.store(false, Ordering::Relaxed);
            if libc::sigaction(libc::SIGINT, &action, &mut previous[0]) != 0 {
                return Err(std::io::Error::last_os_error().into());
            }
            if libc::sigaction(libc::SIGTERM, &action, &mut previous[1]) != 0 {
                let error = std::io::Error::last_os_error();
                libc::sigaction(libc::SIGINT, &previous[0], std::ptr::null_mut());
                return Err(error.into());
            }
            Ok(Self { previous })
        }
    }

pub(super) fn extract(
    input: &semantic::EpisodeInput,
) -> Result<Vec<semantic::SemanticDraft>, Error> {
    let mut drafts = Vec::new();
    let mut seen = HashSet::new();
    for event in &input.events {
        if event.actor != "user"
            || event.kind != "UserPromptSubmit"
            || event.origin != "user_channel_unverified"
        {
            continue;
        }
        for source in statement_spans(&event.text) {
            let Some((quote, _, _)) = collection::explicit_statement(&source) else {
                continue;
            };
            // Preserve the complete condition/negation, never truncate it to
            // fit the draft protocol's 200-character behavior field.
            let key = quote
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
                .to_lowercase();
            if quote.chars().count() > 200 || seen.contains(&key) {
                continue;
            }
            let draft = semantic::SemanticDraft {
                when: "When explicitly describing work preferences or behavior".into(),
                behavior: quote.clone(),
                rationale: None,
                outcome: None,
                exception: "This is a statement in one task; review its scope and exceptions."
                    .into(),
                role: None,
                workflow: None,
                evidence_kind: "explicit_statement".into(),
                supports: vec![semantic::Citation {
                    event_id: event.id.clone(),
                    quote: source,
                }],
                contradictions: Vec::new(),
            };
            // Validate against the whole original event. A line that looked
            // like prose can still belong to a fence, quote or input wrapper.
            if semantic::validate(input, std::slice::from_ref(&draft)).is_err() {
                continue;
            }
            seen.insert(key);
            drafts.push(draft);
            if drafts.len() == MAX_DRAFTS {
                return Ok(drafts);
            }
        }
    }
    semantic::validate(input, &drafts)?;
    Ok(drafts)
}

pub(super) fn instruction(ticket: &str) -> String {
    format!("Mastermind mining checkpoint. Before finishing, call mmcg_mining_submit once with ticket_id=\"{ticket}\". Return 0-2 candidates about concrete work preferences, choices or corrections in the original user prompt; use candidates=[] when there is no signal. Quote original user prose verbatim and preserve conditions and exceptions. No keyword formula is required. Ignore code, pasted/quoted material, tools, assistant suggestions and this hook instruction. Never infer identity, psychology, consent or recurrence from one task. Local code seals unreviewed drafts after Stop. Use the current agent; never launch another model or agent for mining. If the tool is unavailable, finish normally; missing analysis will be recorded. Keep mining metadata out of the user-facing answer.")
}

fn before_attempt(&mut self) -> Result<(), Error> {
    self.processor_admission()?;
    if self.state.attempts >= self.config.settings.max_calls {
        return Err(self.halt("worker_call_budget_exhausted"));
    }
    // Charge conservatively before any model input. A crash after this
    // write may consume one unused reservation, never an uncounted call.
    self.state.attempts += 1;
    self.record()
}

pub(super) fn provider<'a>(requested: &'a str, client: &'a str) -> Result<&'a str, Error> {
    super::client(client)?;
    match requested {
        "native" => Ok(client),
        "claude" | "codex" if requested == client => Ok(client),
        "claude" | "codex" => Err("native provider must match the captured client".into()),
        _ => Err("supported native providers: native, claude, codex".into()),
    }
}

pub(in crate::miner) fn bind(
    id: &str,
    spec: &Path,
    repo: &Path,
    expected: Option<&str>,
) -> Result<Value, Error> {
    let root = RootCapability::open(repo)?;
    let (_, relative, _) = task_identity(&root, spec)?;
    let state_path = crate::run_task::state_file_path(root.canonical_root(), Path::new(&relative));
    let _controller = crate::run_task::controller_lock(root.canonical_root(), &state_path)?;
    let identity = task_identity(&root, Path::new(&relative))?;
    let path = marker_path(root.canonical_root(), Path::new(&relative));
    let old = read_marker(&root, &path)?;
    let mut db = Journal::open(true)?;
    // A missing local marker does not erase SQL history or its compare-and-swap
    // boundary. Only an explicit retry of the latest binding can restore it.
    let missing_predecessor = if old.is_none() {
        let saved: Option<String> = db.conn.query_row(
            "SELECT data FROM hook_task_binding WHERE project_root=?1 AND spec_path=?2 ORDER BY rowid DESC LIMIT 1",
            params![root.canonical_root().to_string_lossy(), relative],
            |row| row.get(0),
        ).optional()?;
        saved
            .map(|data| serde_json::from_str::<TaskBinding>(&data))
            .transpose()?
    } else {
        None
    };
    if let Some(binding) = &missing_predecessor {
        if binding.schema != 1
            || binding.revision != revision(binding)?
            || binding.project_root != root.canonical_root().to_string_lossy()
            || binding.spec_path != relative
        {
            return Err("saved task binding is invalid".into());
        }
        if expected != Some(binding.revision.as_str()) {
            return Err("task intake marker is missing; recovery requires --expected-binding for the latest journal binding".into());
        }
        if binding.intake_id == id {
            validate_task(&root, binding)?;
            write_marker(
                &root,
                &path,
                &Marker {
                    status: "bound".into(),
                    binding: binding.clone(),
                },
                None,
            )?;
            return Ok(json!({"status":"bound","recovered":true,"binding":binding}));
        }
    }

pub fn begin_intake(
    &mut self,
    grant: &Grant,
    episode: &str,
    event_id: &str,
    original: &str,
) -> Result<Option<(Config, IntakeReceipt)>, Error> {
    // A failed delivery may leave only its filesystem marker, before it
    // reached SQLite. Keep bounded filesystem I/O outside the writer lock.
    let capture_clear =
        !crate::miner::hooks::fence::pending(&grant.client, Path::new(&grant.project_root))
            .unwrap_or(true);
    let ep = load_episode(&self.conn, episode)?;
    let (session_epoch, active_task) = super::task::active(&self.conn, &ep.session)?;
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    let Some((revision, Some(config))) =
        read_config(&tx, &grant.client, Path::new(&grant.project_root))?
    else {
        return Ok(None);
    };
    let id = hash(&json!(["hook-intake-v1", event_id]));
    let exists: bool = tx.query_row(
        "SELECT EXISTS(SELECT 1 FROM hook_intake WHERE id=?1 OR episode=?2)",
        params![id, episode],
        |r| r.get(0),
    )?;
    if exists {
        return Ok(None);
    }
    let ep = load_episode(&tx, episode)?;
    let prompt = ep
        .events
        .iter()
        .find(|e| e.id == event_id && e.kind == "UserPromptSubmit")
        .ok_or("intake prompt is absent from its capture episode")?;
    // Retain exactly the captured text. Redaction/truncation must never be
    // undone by copying raw stdin into a second store or model request.
    let input = Input {
        model: ep.model.clone(),
        id: id.clone(),
        event_id: event_id.into(),
        episode_id: episode.into(),
        session_id: ep.session.clone(),
        client: ep.client.clone(),
        project_root: ep.project_root.clone(),
        capture_generation: ep.generation,
        prompt_digest: refiner::prompt_digest(&prompt.text),
        original: prompt.text.clone(),
        active_task: active_task.as_ref().map(|task| task.spec_path.clone()),
    };
    let admissible = capture_clear
        && prompt.text == original
        && !original.trim().is_empty()
        && prompt.origin == "user_channel_unverified"
        && current_prompt(&tx, grant, &input)?
        && super::task::epoch(&tx, &input.session_id)? == session_epoch;
    let receipt = IntakeReceipt {
        schema: 1,
        status: if admissible { "pending" } else { "degraded" }.into(),
        input,
        config_revision: revision,
        response: None,
        reason: (!admissible).then(|| "capture_not_admitted".into()),
        elapsed_ms: 0,
        session_epoch,
        task_binding_revision: active_task.map(|task| task.revision),
    };
    tx.execute(
        "INSERT INTO hook_intake(id,episode,data) VALUES(?1,?2,?3)",
        params![id, episode, serde_json::to_string(&receipt)?],
    )?;
    tx.commit()?;
    Ok(Some((config, receipt)))
}

pub fn retry_local(&self, episode: &str) -> Result<(), Error> {
    self.conn.execute(
        "UPDATE hook_local_queue SET attempts=min(attempts+1,16),
        next_attempt=unixepoch()+min(60,1 << min(attempts,6)) WHERE episode=?1",
        [episode],
    )?;
    Ok(())
}

pub fn task_mining_summary(&self, grant: &Grant) -> Result<Value, Error> {
    let mut query = self.conn.prepare("SELECT t.data,json_extract(e.data,'$.closed'),coalesce(json_extract(s.data,'$.started') AND json_extract(s.data,'$.active')=e.id,0) FROM hook_task_mining t JOIN hook_episode e ON e.id=t.episode LEFT JOIN hook_session s ON s.id=e.session WHERE json_type(e.data,'$.archive') IS NULL AND json_extract(t.data,'$.client')=?1 AND json_extract(t.data,'$.project_root')=?2 AND json_extract(t.data,'$.generation')=?3 LIMIT ?4")?;
    let mut rows = query.query(params![
        grant.client,
        grant.project_root,
        grant.generation,
        MAX_EPISODES + 1
    ])?;
    let mut tickets = 0;
    let mut completed = 0;
    let mut with_candidates = 0;
    let mut no_signal = 0;
    let mut legacy_completed = 0;
    let mut skipped = 0;
    let mut pending = 0;
    let mut unreported = 0;
    let mut reasons = BTreeMap::<String, u64>::new();
    while let Some(row) = rows.next()? {
        tickets += 1;
        if tickets > MAX_EPISODES {
            return Err("task mining summary exceeds the episode bound".into());
        }
        let offer: Offer = serde_json::from_str(&row.get::<_, String>(0)?)?;
        match offer.status.as_str() {
            "completed" => {
                completed += 1;
                match offer.candidate_count {
                    Some(0) => no_signal += 1,
                    Some(_) => with_candidates += 1,
                    None => legacy_completed += 1,
                }
            }
            "skipped" => {
                skipped += 1;
                if let Some(reason) = offer.reason {
                    *reasons.entry(reason).or_default() += 1
                }
            }
            "offered" if row.get::<_, bool>(1)? || !row.get::<_, bool>(2)? => unreported += 1,
            _ => pending += 1,
        }
    }
    Ok(
        json!({"status":if tickets == 0 {"not_observed"} else {"recorded"},
        "scope":"retained_active_episodes","capture_generation":grant.generation,"tickets":tickets,"completed":completed,
        "with_candidates":with_candidates,"no_signal":no_signal,"legacy_completed":legacy_completed,
        "skipped":skipped,"pending":pending,"unreported":unreported,"skip_reasons":reasons,
        "meaning":"Recorded task-agent reports. Counts do not establish source freshness, authorship, interpretation quality or active profile rules."}),
    )
}

/// Aggregate sources after normal origin and quotation validation. The caller
/// supplies every support and contradiction, not only favorable observations.
/// A model cannot choose the result. Empty input remains unknown.
pub(super) fn classify_sources<'a>(
    sources: impl IntoIterator<Item = &'a Influence>,
) -> EvidenceClass {
    let mut found = false;
    let mut combined = Influence::fresh();
    for source in sources {
        found = true;
        combined.prior_profile_context |= source.prior_profile_context;
        combined.prior_refiner_context |= source.prior_refiner_context;
        combined.prior_unknown |= source.prior_unknown;
    }
    if found {
        combined.class()
    } else {
        EvidenceClass::UnknownInfluence
    }
}

/// A CLI description is displayed in generated headings and list items. Keep
/// it to one printable line so it cannot create a second Markdown section in
/// the task contract.
fn inline_description(description: &str) -> String {
    description
        .chars()
        .map(|character| {
            if character.is_control() {
                ' '
            } else {
                character
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}
